var QRMath=require("./QRMath");function QRPolynomial(t,e){if(void 0===t.length)throw new Error(t.length+"/"+e);for(var n=0;n<t.length&&0===t[n];)n++;this.num=new Array(t.length-n+e);for(var g=0;g<t.length-n;g++)this.num[g]=t[g+n]}QRPolynomial.prototype={get:function(t){return this.num[t]},getLength:function(){return this.num.length},multiply:function(t){for(var e=new Array(this.getLength()+t.getLength()-1),n=0;n<this.getLength();n++)for(var g=0;g<t.getLength();g++)e[n+g]^=QRMath.gexp(QRMath.glog(this.get(n))+QRMath.glog(t.get(g)));return new QRPolynomial(e,0)},mod:function(t){if(this.getLength()-t.getLength()<0)return this;for(var e=QRMath.glog(this.get(0))-QRMath.glog(t.get(0)),n=new Array(this.getLength()),g=0;g<this.getLength();g++)n[g]=this.get(g);for(var h=0;h<t.getLength();h++)n[h]^=QRMath.gexp(QRMath.glog(t.get(h))+e);return new QRPolynomial(n,0).mod(t)}},module.exports=QRPolynomial;